    private int calcRemoteFee(Req r, int oldFee) {
        if (!remoteFeeEnabled) return oldFee;
        if (!isRemote(r.province)) return oldFee;
        return oldFee + REMOTE_SURCHARGE;
    }

    private static final int REMOTE_SURCHARGE = 8;

    private boolean isRemote(String province) {
        return "新疆".equals(province) || "西藏".equals(province);
