public class FreightCalc {
    private static final int REMOTE_SURCHARGE = 8;

    private final boolean remoteFeeEnabled;   // 来自现有配置

    public FreightCalc(boolean remoteFeeEnabled) {
        this.remoteFeeEnabled = remoteFeeEnabled;
    }

    public int calc(Req r) {
        int fee = tpl(r.tplId).first;
        if (r.weight > 1.0) {
            int extra = (int) Math.ceil(r.weight - 1.0);
            int unit = tpl(r.tplId).next;
            if (r.vip) unit = unit / 2;
            fee += extra * unit;
        }
        if (region(r.province) != null) fee += region(r.province).surcharge;
        if (r.cod) fee += 2;
        if (remoteFeeEnabled) fee += calcRemoteFee(r);
        return fee;
    }

    int calcRemoteFee(Req r) {
        if (isRemoteProvince(r.province)) return REMOTE_SURCHARGE;
        return 0;
    }

    private static boolean isRemoteProvince(String province) {
        return "新疆".equals(province) || "西藏".equals(province);
    }

    private Tpl tpl(int tplId) {
        if (tplId == 1032) return new Tpl(18, 4);
        throw new IllegalArgumentException("unknown tplId: " + tplId);
    }

    private Region region(String province) {
        if ("新疆".equals(province)) return new Region(3);
        if ("西藏".equals(province)) return new Region(3);
        if ("广东".equals(province)) return new Region(0);
        return null;
    }
}

class Req {
    final int tplId;
    final String province;
    final double weight;
    final boolean vip;
    final boolean cod;

    Req(int tplId, String province, double weight, boolean vip, boolean cod) {
        this.tplId = tplId;
        this.province = province;
        this.weight = weight;
        this.vip = vip;
        this.cod = cod;
    }
}

class Tpl {
    final int first;
    final int next;

    Tpl(int first, int next) {
        this.first = first;
        this.next = next;
    }
}

class Region {
    final int surcharge;

    Region(int surcharge) {
        this.surcharge = surcharge;
    }
}

