package com.example.shipping;

import java.math.BigDecimal;
import java.util.Set;

/**
 * 偏远地区附加费查询。
 *
 * 纯计算：无 I/O、无全局状态、无依赖，构造即可用，便于单测。
 */
public final class RemoteFeeLookup {

    /** 偏远地区附加金额。 */
    private static final BigDecimal REMOTE_SURCHARGE = new BigDecimal("8");

    /** 非偏远地区不加收。 */
    private static final BigDecimal NO_SURCHARGE = BigDecimal.ZERO;

    /**
     * 偏远省份的名称前缀。用前缀匹配，是为了同时吃下简称与全称，
     * 例如 "新疆" 与 "新疆维吾尔自治区"。
     */
    private static final Set<String> REMOTE_PROVINCE_PREFIXES = Set.of("新疆", "西藏");

    /**
     * @param provinceName 省份名，允许简称或全称；null / 空白视为非偏远
     * @return 该省份的偏远附加金额，非偏远为 0
     */
    public BigDecimal surchargeFor(String provinceName) {
        if (provinceName == null) {
            return NO_SURCHARGE;
        }
        String normalized = provinceName.trim();
        if (normalized.isEmpty()) {
            return NO_SURCHARGE;
        }
        for (String prefix : REMOTE_PROVINCE_PREFIXES) {
            if (normalized.startsWith(prefix)) {
                return REMOTE_SURCHARGE;
            }
        }
        return NO_SURCHARGE;
    }
}
