package com.example.shipping.fee;

import java.util.Set;

/**
 * 偏远地区附加费查询。
 *
 * Sprout Class：不依赖任何既有代码，纯函数、无副作用，可独立测试。
 * 接入既有流程时，调用方只需增加一行。
 */
public final class RemoteFeeLookup {

    private static final int REMOTE_SURCHARGE = 8;
    private static final int NO_SURCHARGE = 0;

    /** 用前缀匹配，兼容简称与全称（"西藏" / "西藏自治区"）。 */
    private static final Set<String> REMOTE_PROVINCE_PREFIXES = Set.of("新疆", "西藏");

    /**
     * @param provinceName 省级行政区名称，允许 null 或带首尾空格
     * @return 偏远附加费（元）；非偏远或无法识别时返回 0
     */
    public int surchargeFor(String provinceName) {
        if (provinceName == null) {
            return NO_SURCHARGE;
        }
        String normalized = provinceName.trim();
        for (String prefix : REMOTE_PROVINCE_PREFIXES) {
            if (normalized.startsWith(prefix)) {
                return REMOTE_SURCHARGE;
            }
        }
        return NO_SURCHARGE;
    }
}
```

